import { scriptOfLanguage, type LanguageCode } from '@lexpad/core';
import styles from './script.module.css';

/**
 * The class that makes text in this language readable: its face where we do
 * not bundle one, its tracking, its leading.
 *
 * The writing system is what this turns on — not the language and not the
 * direction. Those three were treated as one thing and it was wrong both
 * ways round: Hebrew is right-to-left and was handed the Persian face,
 * which has no Hebrew letters in it, while a Hindi headword inherited the
 * tracking that makes a Latin headword look deliberate and makes a
 * Devanagari one come apart at the conjuncts.
 *
 * Returns undefined for a script that needs nothing beyond the font stack,
 * which is the common case: Latin, Cyrillic and Greek are already right.
 */
export function scriptClass(lang: LanguageCode): string | undefined {
  return styles[scriptOfLanguage(lang)];
}
